# ==============================================================================
# CODEBASE COPILOT - ALL-IN-ONE SELF-EXTRACTING SINGLE-FILE BUNDLE
# ==============================================================================
# This single Python file contains the complete project architecture and source code.
#
# USAGE:
#   1. Extract & Run:
#         python codebase_copilot_bundle.py
#
#   2. Extract to a custom folder only:
#         python codebase_copilot_bundle.py my_folder --no-run
# ==============================================================================

import os
import sys
import base64
import zlib
from pathlib import Path

FILES = {
  "app.py": "",
  "README.md": "",
  "requirements.txt": "eNpzy0kszrazNdYz0DPgKkotLE0tLim2szXSMzbUM+ACAI5pCIk=",
  "run.bat": "",
  "run.ps1": "",
  "test_app.py": "",
  "agents/bug_detection_agent.py": "",
  "agents/code_review_agent.py": "",
  "agents/code_understanding_agent.py": "",
  "agents/documentation_agent.py": "",
  "agents/improvement_agent.py": "",
  "agents/repository_agent.py": "",
  "agents/__init__.py": "",
  "sample_repo/app.py": "",
  "sample_repo/auth.py": "",
  "sample_repo/models.py": "",
  "sample_repo/requirements.txt": "eNpLy0kszra1NdYz0DPgKkotLE0tLim2tTXSMzYEChRUlgD5drbmYGkAMVUMyA==",
  "sample_repo/utils.py": "",
  "sample_repo/services/payment_service.py": "",
  "sample_repo/static/main.js": "",
  "static/css/style.css": "",
  "static/js/script.js": "",
  "templates/dashboard.html": "",
  "templates/index.html": ""
}

def unpack(target_dir="codebase-copilot"):
    dest = Path(target_dir).resolve()
    print(f"[*] Unpacking Codebase Copilot to: {dest}")
    for rel_path, b64_compressed in FILES.items():
        file_path = dest / rel_path
        file_path.parent.mkdir(parents=True, exist_ok=True)
        raw_bytes = zlib.decompress(base64.b64decode(b64_compressed.encode("ascii")))
        with open(file_path, "wb") as f:
            f.write(raw_bytes)
        print(f"  [+] Created: {rel_path}")
    print("\n[✓] All project files extracted with complete folder architecture!")
    print(f"[*] Project location: {dest}\n")
    return dest

def main():
    target = sys.argv[1] if len(sys.argv) > 1 and not sys.argv[1].startswith("-") else "codebase-copilot"
    dest = unpack(target)
    
    if "--no-run" not in sys.argv:
        print("[*] Installing dependencies...")
        os.chdir(dest)
        os.system(f'"{sys.executable}" -m pip install -r requirements.txt')
        print("\n[🚀] Launching Codebase Copilot server on http://localhost:5000 ...")
        os.system(f'"{sys.executable}" app.py')

if __name__ == "__main__":
    main()
